#ifndef EQEMU_HOUSING_EVOLVING_ITEM_CUSTODY_DB_H
#define EQEMU_HOUSING_EVOLVING_ITEM_CUSTODY_DB_H
#include "evolving_item_custody.h"
#include "house_item_scope_db.h"
#include <iomanip>
#include <sstream>
namespace Housing::EvolvingItemCustody {
inline auto Query(Database& d,const std::string& q){return HouseItemScope::Query(d,q);}
inline std::string N(uint64_t n){return std::to_string(n);}
inline uint64_t U(const char*p){if(!p)throw std::invalid_argument("Missing evolving identity");return std::stoull(p);}
inline bool Installed(Database&d){auto r=Query(d,"SELECT engine FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='housing_evolving_item_locations'");if(!r.RowCount())return false;if(r.RowCount()!=1||!r.begin()[0]||std::string(r.begin()[0])!="InnoDB")throw std::invalid_argument("Invalid evolving locator engine");auto c=Query(d,"SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='housing_evolving_item_locations' AND is_nullable='NO' AND column_type LIKE '%unsigned' AND ((column_name IN ('evolving_id','inventory_guid','custody_id','revision') AND data_type='bigint') OR (column_name IN ('character_id','item_id','slot_id') AND data_type='int') OR (column_name IN ('location_kind','component','path') AND data_type='tinyint'))");if(U(c.begin()[0])!=10)throw std::invalid_argument("Invalid evolving locator columns");auto key=Query(d,"SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='housing_evolving_item_locations' AND index_name='PRIMARY' AND column_name='evolving_id' AND non_unique=0 AND seq_in_index=1");if(U(key.begin()[0])!=1)throw std::invalid_argument("Invalid evolving locator key");return true;}
inline State Read(Database& d,uint64_t id){auto r=Query(d,"SELECT id,character_id,item_id,activated,equipped,current_amount,progression,final_item_id,deleted_at FROM character_evolving_items WHERE id="+N(id)+" FOR UPDATE");if(r.RowCount()!=1)throw std::invalid_argument("Missing evolving item identity");auto x=r.begin();if(x[8])throw std::invalid_argument("Deleted evolving identity");State s;s.id=U(x[0]);s.owner=x[1]?U(x[1]):0;s.item=x[2]?U(x[2]):0;s.activated=x[3]?U(x[3]):0;s.equipped=x[4]?U(x[4]):0;s.amount=x[5]?std::stoll(x[5]):0;s.progression_bits=Bits(x[6]?std::stod(x[6]):0);s.final_item=x[7]?U(x[7]):0;for(int k=1;k<=7;++k)if(!x[k])s.nulls|=1<<(k-1);return s;}
inline bool SameStored(State a,State b,bool held=false){if(held){if((a.nulls&~13)!=(b.nulls&~13))return false;a.owner=b.owner;a.activated=b.activated;a.equipped=b.equipped;a.nulls=b.nulls;}a.component=b.component;a.runtime_progression_bits=b.runtime_progression_bits;return Encode({a})==Encode({b});}
inline void CheckRow(Database&d,const State&s,uint32_t owner,uint32_t slot){auto r=Query(d,"SELECT item_id,augment_one,augment_two,augment_three,augment_four,augment_five,augment_six FROM inventory WHERE character_id="+N(owner)+" AND slot_id="+N(slot)+" FOR UPDATE");if(r.RowCount()!=1||U(r.begin()[s.component])!=s.item)throw std::invalid_argument("Evolving inventory component changed");}
inline void CheckLocator(Database&d,const State&s,uint32_t owner,uint32_t slot){auto r=Query(d,"SELECT location_kind,character_id,item_id,slot_id,component FROM housing_evolving_item_locations WHERE evolving_id="+N(s.id)+" FOR UPDATE");if(r.RowCount()){auto x=r.begin();if(r.RowCount()!=1||U(x[0])!=1||U(x[1])!=owner||U(x[2])!=s.item||U(x[3])!=slot||U(x[4])!=s.component)throw std::invalid_argument("Evolving inventory locator changed");return;}
 // An unbound legacy template can only be adopted when both identities are unique.
 auto count=Query(d,"SELECT COALESCE(SUM((item_id="+N(s.item)+")+(augment_one="+N(s.item)+")+(augment_two="+N(s.item)+")+(augment_three="+N(s.item)+")+(augment_four="+N(s.item)+")+(augment_five="+N(s.item)+")+(augment_six="+N(s.item)+")),0) FROM inventory WHERE character_id="+N(owner));auto ce=Query(d,"SELECT id FROM character_evolving_items WHERE character_id="+N(owner)+" AND item_id="+N(s.item)+" AND deleted_at IS NULL FOR UPDATE");if(U(count.begin()[0])!=1||ce.RowCount()!=1||U(ce.begin()[0])!=s.id)throw std::invalid_argument("Ambiguous legacy evolving identity");}
inline void ValidateInventory(Database&d,const Bytes&b,uint32_t owner,uint32_t slot){for(auto&s:Decode(b)){if(s.owner!=owner)throw std::invalid_argument("Wrong evolving owner");CheckRow(d,s,owner,slot);auto actual=Read(d,s.id);if(!SameStored(actual,s))throw std::invalid_argument("Evolving progress changed");CheckLocator(d,s,owner,slot);}}
inline Bytes Capture(Database&d,uint32_t owner,uint32_t slot,const EQ::ItemInstance& item){if(!Has(item))return {};if(!Installed(d))throw std::invalid_argument("Evolving custody schema missing");std::vector<State> states;auto& mutable_item=const_cast<EQ::ItemInstance&>(item);for(unsigned k=0;k<=6;++k){auto*n=Component(mutable_item,k);if(!n||!n->IsEvolving())continue;auto s=Read(d,n->GetEvolveUniqueID());s.component=k;s.runtime_progression_bits=Bits(n->GetEvolveProgression());states.push_back(s);}auto b=Encode(states);if(!Matches(b,mutable_item,owner))throw std::invalid_argument("Evolving memory identity changed");ValidateInventory(d,b,owner,slot);return b;}
inline void StoreHold(Database&d,const Bytes&b,uint64_t custody,uint8_t path=0){if(!custody||path>EQ::invbag::SLOT_COUNT)throw std::invalid_argument("Invalid evolving custody location");for(auto&s:Decode(b)){if(!SameStored(Read(d,s.id),s))throw std::invalid_argument("Evolving hold progress changed");auto loc=Query(d,"SELECT location_kind,character_id,item_id,component FROM housing_evolving_item_locations WHERE evolving_id="+N(s.id)+" FOR UPDATE");if(loc.RowCount()&&(U(loc.begin()[0])!=1||U(loc.begin()[1])!=s.owner||U(loc.begin()[2])!=s.item||U(loc.begin()[3])!=s.component))throw std::invalid_argument("Evolving item already held");Query(d,"UPDATE character_evolving_items SET character_id=0,activated=0,equipped=0 WHERE id="+N(s.id));Query(d,"INSERT INTO housing_evolving_item_locations(evolving_id,location_kind,character_id,item_id,slot_id,inventory_guid,component,custody_id,path,revision) VALUES("+N(s.id)+",2,"+N(s.owner)+","+N(s.item)+",0,0,"+N(s.component)+","+N(custody)+","+N(path)+",1) ON DUPLICATE KEY UPDATE location_kind=2,slot_id=0,inventory_guid=0,custody_id=VALUES(custody_id),path=VALUES(path),revision=revision+1");}}
inline void ValidateHeld(Database&d,const Bytes&b,uint64_t custody,uint8_t path=0){for(auto&s:Decode(b)){auto r=Query(d,"SELECT location_kind,character_id,item_id,component,custody_id,path FROM housing_evolving_item_locations WHERE evolving_id="+N(s.id)+" FOR UPDATE");if(r.RowCount()!=1)throw std::invalid_argument("Missing held evolving locator");auto x=r.begin();if(U(x[0])!=2||U(x[1])!=s.owner||U(x[2])!=s.item||U(x[3])!=s.component||U(x[4])!=custody||U(x[5])!=path)throw std::invalid_argument("Wrong held evolving identity");auto a=Read(d,s.id);if(a.owner||a.activated||a.equipped||!SameStored(a,s,true))throw std::invalid_argument("Held evolving progress changed");}}
inline std::string Decimal(uint64_t bits){std::ostringstream o;o<<std::setprecision(17)<<Float(bits);return o.str();}
inline Bytes ReturnRelease(Database&d,const Bytes&b,uint64_t custody,uint8_t path,uint32_t owner,uint32_t slot,uint64_t guid){ValidateHeld(d,b,custody,path);auto states=Decode(b);if(!owner)throw std::invalid_argument("Missing evolving recipient");for(auto&s:states){auto value=[&](unsigned bit,const std::string& n){return s.nulls&(1<<bit)?std::string("NULL"):n;};Query(d,"UPDATE character_evolving_items SET character_id="+N(owner)+",activated="+value(2,N(s.activated))+",equipped="+value(3,N(s.equipped))+",current_amount="+value(4,std::to_string(s.amount))+",progression="+value(5,Decimal(s.progression_bits))+",final_item_id="+value(6,N(s.final_item))+" WHERE id="+N(s.id));Query(d,"UPDATE housing_evolving_item_locations SET location_kind=1,character_id="+N(owner)+",slot_id="+N(slot)+",inventory_guid="+N(guid)+",custody_id=0,path=0,revision=revision+1 WHERE evolving_id="+N(s.id));s.owner=owner;}return Encode(states);}
// Exact loader resolution precedes legacy template fallback. Missing tracked UID
// is an integrity failure, never permission to allocate a replacement identity.
inline uint64_t InventoryIdentity(Database&d,uint32_t owner,uint32_t slot,uint8_t component,uint32_t item,uint64_t guid){
 if(!Installed(d))return 0;
 auto r=Query(d,"SELECT evolving_id,inventory_guid FROM housing_evolving_item_locations WHERE location_kind=1 AND character_id="+N(owner)+" AND slot_id="+N(slot)+" AND component="+N(component)+" AND item_id="+N(item));
 uint64_t selected=0;for(auto x:r)if(U(x[1])==guid){if(selected)throw std::invalid_argument("Duplicate evolving inventory GUID");selected=U(x[0]);}
 if(!selected&&r.RowCount()==1)selected=U(r.begin()[0]);
 if(r.RowCount()&&!selected)throw std::invalid_argument("Ambiguous evolving inventory binding");
 if(selected){auto s=Read(d,selected);if(s.owner!=owner||s.item!=item)throw std::invalid_argument("Tracked evolving identity unavailable");}
 return selected;
}
inline bool Held(Database&d,uint64_t id){if(!Installed(d))return false;auto r=Query(d,"SELECT location_kind FROM housing_evolving_item_locations WHERE evolving_id="+N(id));return r.RowCount()&&U(r.begin()[0])==2;}
// Ordinary moves retain the same identity; this never creates or replaces CEI.
inline void BindInventory(Database&d,uint32_t owner,uint32_t slot,const EQ::ItemInstance&item){if(!Installed(d))return;auto&mutable_item=const_cast<EQ::ItemInstance&>(item);for(unsigned k=0;k<=6;++k){auto*n=Component(mutable_item,k);if(!n||!n->IsEvolving()||!n->GetEvolveUniqueID())continue;auto s=Read(d,n->GetEvolveUniqueID());if(s.owner!=owner||s.item!=n->GetID()||Held(d,s.id))throw std::invalid_argument("Held or foreign evolving inventory save");Query(d,"INSERT INTO housing_evolving_item_locations(evolving_id,location_kind,character_id,item_id,slot_id,inventory_guid,component,custody_id,path,revision) VALUES("+N(s.id)+",1,"+N(owner)+","+N(s.item)+","+N(slot)+","+N(item.GetSerialNumber())+","+N(k)+",0,0,1) ON DUPLICATE KEY UPDATE location_kind=1,character_id=VALUES(character_id),item_id=VALUES(item_id),slot_id=VALUES(slot_id),inventory_guid=VALUES(inventory_guid),component=VALUES(component),custody_id=0,path=0,revision=revision+1");}}

inline bool InventorySaveAllowed(Database&d,uint32_t owner,const EQ::ItemInstance&item){
 auto& root=const_cast<EQ::ItemInstance&>(item);
 for(unsigned c=0;c<=6;++c){auto*n=Component(root,c);if(!n||!n->IsEvolving()||!n->GetEvolveUniqueID())continue;auto s=Read(d,n->GetEvolveUniqueID());if(s.owner!=owner||s.item!=n->GetID()||Held(d,s.id))return false;}
 if(item.IsClassBag())for(unsigned c=0;c<EQ::invbag::SLOT_COUNT;++c)if(auto*n=item.GetItem(c);n&&!InventorySaveAllowed(d,owner,*n))return false;
 return true;
}

}
#endif
